class Solution{

    static int maximumRobots(int[] charge,int[] run,long budget){

        Deque<Integer> dq=new ArrayDeque<>();

        long total=0;
        int left=0,ans=0;

        for(int right=0;right<charge.length;right++){

            while(!dq.isEmpty() && charge[dq.peekLast()]<=charge[right])
                dq.pollLast();

            dq.addLast(right);

            total+=run[right];

            while(!dq.isEmpty() && charge[dq.peekFirst()] + (right-left+1)*total > budget){

                if(dq.peekFirst()==left)
                    dq.pollFirst();

                total-=run[left];
                left++;
            }

            ans=Math.max(ans,right-left+1);
        }

        return ans;
    }

    public static void main(String[] args){

        Scanner sc=new Scanner(System.in);
        String line=sc.nextLine();

        Matcher m1=Pattern.compile("charge=\\[(.*?)\\]").matcher(line);
        Matcher m2=Pattern.compile("run=\\[(.*?)\\]").matcher(line);
        Matcher m3=Pattern.compile("budget=(\\d+)").matcher(line);

        m1.find(); m2.find(); m3.find();

        String[] a=m1.group(1).split(",");
        String[] b=m2.group(1).split(",");

        int n=a.length;

        int[] charge=new int[n];
        int[] run=new int[n];

        for(int i=0;i<n;i++){
            charge[i]=Integer.parseInt(a[i].trim());
            run[i]=Integer.parseInt(b[i].trim());
        }

        long budget=Long.parseLong(m3.group(1));

        System.out.println(maximumRobots(charge,run,budget));
    }
}

