    queue<pair<int,int>> q;
    int fresh = 0, mins = 0;

    for(int i=0;i<m;i++){
        for(int j=0;j<n;j++){
            if(grid[i][j]==2) q.push({i,j});
            if(grid[i][j]==1) fresh++;
        }
    }

    vector<int> dirs = {-1,0,1,0,-1};

    while(!q.empty() && fresh>0){

        int size=q.size();

