            q.pop();

            for(int d=0;d<4;d++){

                int nx=x+dirs[d];
                int ny=y+dirs[d+1];

                if(nx>=0 && ny>=0 && nx<m && ny<n && grid[nx][ny]==1){

                    grid[nx][ny]=2;
                    fresh--;
                    q.push({nx,ny});
                }
            }
        }

        mins++;
    }

    return fresh==0?mins:-1;
}

